import '/dev.js';
import {renderAuth} from './auth.js';
import {escapeHtml as esc,avatar,themeClass,tagList,svg,uiIcons,imageSrc} from './ui.js';
import {profileMarkup,openProfileEditor} from './profile.js';
import {composerTeaser,openComposer,postMarkup} from './composer.js';
import {startTutorial,closeTutorial,mountTutorial} from './tutorial.js';
const $=selector=>document.querySelector(selector);
let state={profiles:[],posts:[],saved:[],liked:[],skipped:[],active:null,recommendations:[],feedOrder:[]};
let page='Home',tab='Für dich',query='',viewedProfile=null,lastSwipe=null,swiping=false,toastTimer;
const pending=new Set();
const icons={Home:svg('<path d="m3 10 9-7 9 7v10H15v-7H9v7H3Z"/>'),Entdecken:svg('<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>'),Connections:uiIcons.heart,Lesezeichen:uiIcons.bookmark,Art:svg('<path d="m16 3 5 5-10 10-5-5Z"/><path d="M6 13c-4 0-4 4-4 7 3 0 7 0 7-4"/>'),Design:svg('<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M3 9h18M9 9v12"/>'),Profil:svg('<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>')};
const me=()=>state.profiles.find(p=>p.id===state.active);
const brand=()=>'<a class="brand" href="/" data-home aria-label="VConnect Home"><span class="brand-mark">v<span>✦</span></span>vconnect<span class="brand-period">.</span></a>';
async function api(path,body){let response;try{response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined})}catch{throw new Error('Verbindung unterbrochen. Bitte erneut versuchen.')}let data;try{data=await response.json()}catch{throw new Error('Der Server konnte die Anfrage nicht beantworten.')}if(!response.ok)throw new Error(data.error||'Anfrage fehlgeschlagen.');return data}
function accept(data){if(state.active!==data.active){lastSwipe=null;closeTutorial()}state=data}
async function commit(path,body){accept(await api(path,body));render()}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function safe(action){return async event=>{try{await action(event)}catch(error){toast(error.message)}}}
function navigate(path){history.pushState({},'',path);if(path==='/'){page='Home';viewedProfile=null;}render();window.scrollTo(0,0)}
function auth(){navigate('/login')}
function go(next){page=next;history.pushState({},'',next==='Home'?'/':'/#'+next.toLowerCase());tab='Für dich';query='';viewedProfile=null;render();window.scrollTo(0,0)}
function viewProfile(id){history.pushState({},'','/#profil/'+encodeURIComponent(id));viewedProfile=id;page='Profil';render();window.scrollTo(0,0)}
function editProfile(initialTab='identity'){if(!me())return auth();openProfileEditor({profile:me(),initialTab,onSave:async profile=>{await commit('/api/profile',profile);toast('Dein Profil wurde gespeichert.')}})}
function compose(){if(!me())return auth();openComposer({profile:me(),topic:['Art','Design'].includes(page)?page.toLowerCase():'general',onPublish:async draft=>{await commit('/api/posts',draft);toast('Dein Beitrag ist veröffentlicht.')}})}
function empty(symbol,title,text,button=''){return `<section class="empty"><div class="empty-symbol">${symbol}</div><h2>${title}</h2><p>${text}</p>${button}</section>`}
function posts(){let items=state.posts.filter(p=>page!=='Lesezeichen'||state.saved.includes(p.id)).filter(p=>tab!=='Connections'||state.liked.includes(p.author)||p.author===state.active).filter(p=>!query||p.text.toLowerCase().includes(query.toLowerCase())).filter(p=>!['Art','Design'].includes(page)||p.topic===page.toLowerCase());if(tab==='Für dich'&&page==='Home'){const order=new Map(state.feedOrder.map((id,i)=>[id,i]));items.sort((a,b)=>(order.get(a.id)??999)-(order.get(b.id)??999))}else items.sort((a,b)=>b.date-a.date);return items.length?items.map(p=>postMarkup(p,state.profiles.find(a=>a.id===p.author),{saved:state.saved.includes(p.id),own:p.author===state.active})).join(''):empty(page==='Lesezeichen'?'▱':'✦',query?'Keine Beiträge gefunden.':page==='Lesezeichen'?'Für später. Für dich.':page==='Art'?'Zeig, was du erschaffst.':page==='Design'?'Woran arbeitest du gerade?':'Hier beginnt deine Timeline.',query?'Versuche einen anderen Suchbegriff.':page==='Lesezeichen'?'Merke dir Beiträge über das Lesezeichen-Symbol.':['Art','Design'].includes(page)?'Teile den ersten Beitrag in diesem Kanal.':'Teile einen Gedanken oder entdecke neue Profile.',['Home','Art','Design'].includes(page)?'<button class="secondary" data-compose>Ersten Beitrag erstellen ↗</button>':'')}
function candidates(){const map=new Map(state.profiles.map(p=>[p.id,p]));const ordered=state.recommendations.length?state.recommendations:state.profiles.map(p=>({id:p.id,reasons:['Etwas Neues entdecken']}));return ordered.map(r=>({...map.get(r.id),reasons:r.reasons})).filter(p=>p.id&&p.id!==state.active&&p.role==='VTuber'&&!state.liked.includes(p.id)&&!state.skipped.includes(p.id)&&(tab!=='Collabs'||p.collab)&&(!query||(p.name+' '+(p.username||'')+' '+p.tags+' '+(p.languages||'')).toLowerCase().includes(query.toLowerCase())))}
function discover(){const list=candidates(),p=list[0];return `<div class="discover-heading"><div><span class="eyebrow">DEINE NÄCHSTE CONNECTION</span><h1>Gleicher Vibe?<br><span>Finde es heraus.</span></h1></div><span class="discovery-count">${list.length} Profile</span></div><div class="discover-tabs"><button data-mode="Alle" class="${tab!=='Collabs'?'selected':''}">Für dich entdecken</button><button data-mode="Collabs" class="${tab==='Collabs'?'selected':''}">✧ Collab-Partner</button></div>${query?`<div class="search-summary">Suche: ${esc(query)} <button id="clearSearch" aria-label="Suche zurücksetzen">×</button></div>`:''}${p?`<div class="swipe-stage ${themeClass(p)}"><article class="swipe-card ${themeClass(p)}" tabindex="0" aria-label="${esc(p.name)}. Mit Pfeiltasten links oder rechts swipen."><div class="swipe-intent intent-yes">MERKEN ♡</div><div class="swipe-intent intent-no">WEITER ↗</div><div class="card-art banner-${['orbit','grid','waves'].includes(p.banner)?p.banner:'orbit'}">${imageSrc(p.bannerImage)?`<img class="card-banner-image" src="${esc(imageSrc(p.bannerImage))}" alt="" decoding="async">`:'<div class="banner-lines"></div>'}${p.demo?'<span class="card-demo">Demo-Profil</span>':''}${avatar(p,'swipe-avatar')}<span class="card-corner-spark">✦</span>${p.collab?'<span class="card-availability"><i></i> Offen für Collabs</span>':''}</div><div class="card-info"><div class="card-title-row"><div><button class="card-profile-name" data-profile="${esc(p.id)}">${esc(p.name)}</button><span class="card-role">${p.username?'@'+esc(p.username)+' · ':''}${esc(p.role)}${p.pronouns?' · '+esc(p.pronouns):''}</span></div><button class="card-open" data-profile="${esc(p.id)}" aria-label="Profil öffnen">↗</button></div><p>${esc(p.bio)}</p><div class="interest-pills">${tagList(p.tags).slice(0,5).map(t=>`<span>${esc(t)}</span>`).join('')}</div>${p.languages?`<div class="card-language">◎ ${esc(p.languages)}</div>`:''}<div class="recommendation-reason">✧ ${esc(p.reasons?.[0]||'Etwas Neues entdecken')}</div></div></article></div><div class="swipe-action-row"><div><button class="swipe-pass" data-swipe="skip" data-id="${esc(p.id)}" aria-label="Überspringen">${uiIcons.close}</button><small>Weiter</small></div><div><button class="swipe-undo" id="undoSwipe" ${lastSwipe?'':'disabled'} aria-label="Letzten Swipe rückgängig machen">↶</button><small>Rückgängig</small></div><div><button class="swipe-like" data-swipe="like" data-id="${esc(p.id)}" aria-label="Merken">${uiIcons.heart}</button><small>Merken</small></div></div><p class="hint">Ziehen, Buttons oder ← → verwenden${!state.active?'<br><span>Als Gast bleiben deine Swipes nur bis zum Neuladen erhalten.</span>':''}</p>`:empty('✧',query?'Kein Profil für diese Suche.':'Alle Profile entdeckt.',query?'Versuche einen anderen Namen, eine Sprache oder ein Interesse.':'Deine gemerkten Profile findest du in Connections.',`<button class="secondary" id="resetSwipes">Swipes zurücksetzen</button>`)}`}
function connections(){const items=state.profiles.filter(p=>state.liked.includes(p.id));return `<div class="section-intro"><span class="eyebrow">DEINE AUSWAHL</span><h1>Connections, die bleiben.</h1><p>Gemerkte Profile für den nächsten Stream oder deine nächste Collab.</p></div>${items.length?`<div class="connection-list">${items.map(p=>`<article class="connection-item ${themeClass(p)}"><button data-profile="${esc(p.id)}" class="connection-person">${avatar(p)}<span><strong>${esc(p.name)} ${p.demo?'<small class="demo-badge">Demo</small>':''}</strong><small>${esc(p.tags||p.role)}</small></span></button><button class="icon-control" data-profile="${esc(p.id)}" aria-label="Profil von ${esc(p.name)} öffnen">↗</button></article>`).join('')}</div>`:empty('♡','Noch keine Connections.','Merke dir beim Swipen Profile, die dich interessieren.','<button class="primary" data-page="Entdecken">VTuber entdecken ↗</button>')}`}
function feed(){return `<div class="feed-tabs">${['Für dich','Neueste','Connections'].map(t=>`<button data-tab="${t}" class="${tab===t?'selected':''}">${t}</button>`).join('')}</div>${composerTeaser(me())}${posts()}`}
const hubIcons={Art:'✧',Design:'◇'};
function hubPage(hub){const art=hub==='Art';return `<section class="channel-heading channel-${hub.toLowerCase()}"><div class="channel-avatar">${hubIcons[hub]}</div><div><span class="eyebrow">COMMUNITY-KANAL</span><h1>${hub}</h1><p>${art?'Für Künstler, ihre Werke und kreative Ideen.':'Für Programmierer, Projekte und guten Code.'}</p></div></section>${composerTeaser(me())}<div class="channel-feed-label">Neueste Beiträge <span>${art?'Kunst & Austausch':'Code & Projekte'}</span></div>${posts()}`}
function rightbar(){const channel=['Art','Design'].includes(page)?page:null;const list=candidates().slice(0,2);return `<aside class="rightbar"><label class="search"><span>⌕</span><input id="search" placeholder="Beiträge & VTuber suchen" value="${esc(query)}" aria-label="VConnect durchsuchen"></label>${channel?`<section class="channel-about"><span class="eyebrow">ÜBER DIESEN KANAL</span><h2>${channel==='Art'?'Raum für deine Kunst.':'Von Idee zu Code.'}</h2><p>${channel==='Art'?'Teile eigene Illustrationen, Skizzen und andere Arbeiten. Tausche Feedback aus und finde andere kreative Köpfe.':'Zeig Projekte, teile Code oder stell eine Frage. Ein Ort für Programmierer in der VTuber-Community.'}</p><div class="channel-note">${channel==='Art'?'Gib Credits, wenn du Arbeiten anderer teilst.':'Bitte keine Zugangsdaten oder privaten Schlüssel posten.'}</div></section>`:list.length?`<section class="compact-creators"><h3>Neue Profile entdecken</h3>${list.map(p=>`<button data-profile="${esc(p.id)}">${avatar(p)}<span><strong>${esc(p.name)}</strong><small>${p.demo?'Demo-Profil':esc(p.tags||p.role)}</small></span><b>↗</b></button>`).join('')}</section>`:''}<section class="channel-list"><h3>Community-Kanäle</h3><button data-page="Art"><span>✧</span><div><strong>Art</strong><small>Künstler & ihre Arbeiten</small></div><b>↗</b></button><button data-page="Design"><span>◇</span><div><strong>Design</strong><small>Programmierung & Projekte</small></div><b>↗</b></button></section><button id="startTour" class="compact-tour"><span>✧</span><div><strong>VConnect kennenlernen</strong><small>${state.onboarding?.status==='completed'?'Tour erneut ansehen':state.onboarding?.step?'Bei Schritt '+(state.onboarding.step+1)+' fortsetzen':'Geführte Tour starten'}</small></div><b>→</b></button><footer>VConnect © ${new Date().getFullYear()}</footer></aside>`}
function render(){
 if(['/login','/register'].includes(location.pathname)){closeTutorial();$('#tutorialPanel')?.remove();renderAuth({register:location.pathname==='/register',api,navigate,onSuccess:data=>{const isNew=location.pathname==='/register';accept(data);if(isNew)startTutorial();navigate('/');toast('Du bist angemeldet.')}});return}
 document.title='VConnect · '+(page==='Home'?'Feed':page);const p=me(),shown=state.profiles.find(x=>x.id===(viewedProfile||state.active));
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<nav>${['Home','Entdecken','Connections','Lesezeichen','Profil','Art','Design'].map(label=>[label,icons[label]]).map(([label,icon])=>`${label==='Art'?'<div class="nav-group-label">KANÄLE</div>':''}<button data-page="${label}" class="${page===label?'active':''}" ${page===label?'aria-current="page"':''}><span>${icon}</span><span class="nav-label">${label}</span></button>`).join('')}</nav><button class="post-button" id="write" aria-label="Beitrag erstellen" aria-keyshortcuts="N"><i class="write-orb">${uiIcons.pen}<span>✦</span></i><span class="write-copy"><strong>Posten</strong><small>Teile einen Moment</small></span><b>↗</b></button><div class="sidebar-bottom"><button id="account" class="account">${avatar(p)}<span><strong>${esc(p?.name||'Anmelden')}</strong><small>${p?'Mein Profil':'Konto erstellen oder anmelden'}</small></span><b>···</b></button>${p?'<button id="logout" class="logout">Abmelden</button>':''}</div></aside><main><header><strong>${page==='Home'?'Dein Feed':page==='Profil'&&shown?esc(shown.name):page}</strong><div class="header-tools"><button id="headerTour" aria-label="VConnect Tutorial öffnen">✧</button><button data-page="Entdecken" aria-label="VTuber entdecken">${icons.Entdecken}</button>${!p?'<button class="header-login" id="headerLogin">Anmelden ↗</button>':''}</div></header><div class="mobile-hub-nav">${['Art','Design'].map(h=>`<button data-page="${h}" class="${page===h?'selected':''}">${hubIcons[h]} ${h}</button>`).join('')}</div>${page==='Home'?feed():['Art','Design'].includes(page)?hubPage(page):page==='Entdecken'?discover():page==='Profil'?(shown?profileMarkup(shown,{own:shown.id===state.active}):empty('◎','Dein Profil wartet.','Melde dich an, um dein Profil zu gestalten.','<button class="primary" id="createProfile">Anmelden ↗</button>')):page==='Connections'?connections():`<div class="section-intro"><span class="eyebrow">FÜR SPÄTER</span><h1>Deine Lesezeichen.</h1><p>Gespeicherte Beiträge an einem Ort.</p></div>${posts()}`}</main>${rightbar()}<button class="mobile-write" data-compose aria-label="Beitrag erstellen">${uiIcons.pen}</button></div>`;
 bind();mountTutorial({state,go,edit:editProfile,compose,save:data=>commit('/api/onboarding',data),updateProfile:role=>commit('/api/profile',{...me(),role})});
}
function bind(){
 document.querySelectorAll('[data-edit-design]').forEach(b=>b.onclick=()=>editProfile('design'));document.querySelectorAll('[data-edit-links]').forEach(b=>b.onclick=()=>editProfile('links'));
 document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>{page='Entdecken';tab='Für dich';query=b.dataset.topic;render();window.scrollTo(0,0)});
 document.querySelectorAll('[data-home]').forEach(a=>a.onclick=e=>{e.preventDefault();go('Home')});
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));
 document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>viewProfile(b.dataset.profile));
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{tab=b.dataset.mode;render()});
 for(const id of ['headerLogin','createProfile'])if($('#'+id))$('#'+id).onclick=auth;
 if($('#account'))$('#account').onclick=()=>me()?viewProfile(state.active):auth();
 if($('#editProfile'))$('#editProfile').onclick=()=>editProfile();
 for(const id of ['logout','logoutProfile'])if($('#'+id))$('#'+id).onclick=safe(async()=>{await commit('/api/logout',{});page='Home';navigate('/login')});
 for(const id of ['write','composeOpen','quickPost'])if($('#'+id))$('#'+id).onclick=compose;
 document.querySelectorAll('[data-compose]').forEach(b=>b.onclick=compose);
 for(const id of ['startTour','sidebarTour','headerTour'])if($('#'+id))$('#'+id).onclick=safe(async()=>{if(!me())return auth();const step=state.onboarding?.status==='completed'?0:state.onboarding?.step??0;startTutorial();await commit('/api/onboarding',{step,status:'active'})});
 document.querySelectorAll('[data-like],[data-save]').forEach(button=>button.onclick=safe(async()=>{if(!me())return auth();const id=button.dataset.like||button.dataset.save,kind=button.dataset.like?'post-like':'save',key=kind+id;if(pending.has(key))return;pending.add(key);button.disabled=true;try{const enabled=kind==='post-like'?!state.posts.find(p=>p.id===id)?.liked:!state.saved.includes(id);await commit('/api/interactions',{target:id,kind,enabled})}finally{pending.delete(key);button.disabled=false}}));
 document.querySelectorAll('[data-share]').forEach(button=>button.onclick=safe(async()=>{try{const post=state.posts.find(p=>p.id===button.dataset.share);await navigator.clipboard.writeText([post.text,post.image?new URL(post.image,location.origin).href:''].filter(Boolean).join('\n'));toast('Beitrag kopiert.')}catch{throw new Error('Die Zwischenablage ist nicht verfügbar.')}}));
 $('#search').onchange=event=>{query=event.target.value;render()};
 if($('#clearSearch'))$('#clearSearch').onclick=()=>{query='';render()};
 document.querySelectorAll('[data-swipe]').forEach(button=>button.onclick=()=>swipe(button.dataset.id,button.dataset.swipe));
 if($('#undoSwipe'))$('#undoSwipe').onclick=safe(async()=>{if(!lastSwipe||swiping)return;const previous=lastSwipe;if(state.active)await commit('/api/undo-swipe',{target:previous.id});else{state.liked=state.liked.filter(id=>id!==previous.id);state.skipped=state.skipped.filter(id=>id!==previous.id)}lastSwipe=null;render();toast('Letzter Swipe zurückgenommen.')});
 if($('#resetSwipes'))$('#resetSwipes').onclick=safe(async()=>{if(state.active)await commit('/api/reset-swipes',{});else{state.liked=[];state.skipped=[]}lastSwipe=null;render()});
 bindDrag();
}
function bindDrag(){const card=$('.swipe-card');if(!card)return;let start=null,delta=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;const reset=()=>{start=null;delta=0;card.classList.remove('dragging','intent-like','intent-skip');card.style.transform=''};
 card.onpointerdown=event=>{if(swiping||event.button!==0||event.target.closest('button,a'))return;start=event.clientX;delta=0;card.classList.add('dragging');card.setPointerCapture(event.pointerId)};
 card.onpointermove=event=>{if(start===null)return;delta=Math.max(-220,Math.min(220,event.clientX-start));if(!reduced)card.style.transform='translateX('+delta+'px) rotate('+(delta/18)+'deg)';card.classList.toggle('intent-like',delta>35);card.classList.toggle('intent-skip',delta< -35)};
 card.onpointerup=()=>{if(start===null)return;const action=delta>75?'like':delta< -75?'skip':null;const id=candidates()[0]?.id;reset();if(action&&id)swipe(id,action)};card.onpointercancel=reset;
 card.onkeydown=event=>{if(event.target!==card||!['ArrowLeft','ArrowRight'].includes(event.key))return;event.preventDefault();swipe(candidates()[0].id,event.key==='ArrowRight'?'like':'skip')};
}
async function swipe(id,action){if(swiping)return;swiping=true;const card=$('.swipe-card');try{if(card&&!matchMedia('(prefers-reduced-motion: reduce)').matches){card.classList.add(action==='like'?'depart-right':'depart-left');await new Promise(resolve=>setTimeout(resolve,260))}if(state.active)accept(await api('/api/interactions',{target:id,kind:action}));else state[action==='like'?'liked':'skipped'].push(id);lastSwipe={id,action};render();if(action==='like')toast('Profil in deinen Connections gemerkt.')}catch(error){render();toast(error.message)}finally{swiping=false}}
window.addEventListener('keydown',event=>{if(event.key.toLowerCase()==='n'&&!event.ctrlKey&&!event.altKey&&!event.metaKey&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&!document.querySelector('dialog[open]')&&!['/login','/register'].includes(location.pathname)){event.preventDefault();compose()}});
function readHash(){const [route,id]=location.hash.slice(1).split('/');const map={home:'Home',entdecken:'Entdecken',connections:'Connections',lesezeichen:'Lesezeichen',profil:'Profil',art:'Art',flow:'Home',design:'Design'};page=map[route]||'Home';viewedProfile=id&&/^(demo-[1-6]|[a-f0-9-]{36})$/.test(id)?id:null}
window.addEventListener('popstate',()=>{readHash();render()});readHash();
render();try{accept(await api('/api/state'));render()}catch(error){toast(error.message)}
